import type { ButtonHTMLAttributes, DetailsHTMLAttributes, HTMLAttributes } from "react";

export function DropdownMenu({ className = "", ...props }: DetailsHTMLAttributes<HTMLDetailsElement>) { return <details className={`co-group co-relative co-inline-block ${className}`.trim()} {...props} />; }
export function DropdownMenuTrigger({ className = "", children, ...props }: HTMLAttributes<HTMLElement>) { return <summary className={`co-flex co-cursor-pointer co-list-none co-items-center co-justify-between co-gap-2 focus-visible:co-ring-2 ${className}`.trim()} {...props}>{children}<span aria-hidden="true" className="co-inline-block co-transition group-open:co-rotate-180">↓</span></summary>; }
export function DropdownMenuContent({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div role="menu" className={`co-absolute co-end-0 co-z-50 co-mt-2 co-min-w-44 co-rounded-md co-border co-border-black/15 co-bg-white co-p-1 co-shadow-lg ${className}`.trim()} {...props} />; }
export function DropdownMenuItem({ className = "", ...props }: ButtonHTMLAttributes<HTMLButtonElement>) { return <button role="menuitem" type="button" className={`co-block co-w-full co-rounded co-px-3 co-py-2 co-text-left co-text-sm hover:co-bg-black/5 focus-visible:co-ring-2 disabled:co-opacity-40 ${className}`.trim()} {...props} />; }
